const $=s=>document.querySelector(s), root=$('#app'), dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',train:'m6 4-2 2 14 14 2-2M3 9l6-6M15 21l6-6M2 7l5-5M17 22l5-5',library:'M4 4h6v16H4ZM14 4h6v16h-6M7 8h0M17 8h0',chart:'M4 3v17h17M8 15l4-5 4 2 4-7',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
const button=(label,cmd,style='secondary',data='')=>`<button type="button" class="${style}" data-cmd="${cmd}" ${data}>${label}</button>`;
const input=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const textarea=(name,label,value='',max=1000)=>`<label>${label}<textarea name="${name}" maxlength="${max}">${esc(value)}</textarea></label>`;
const options=(values,selected)=>values.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');
const select=(name,label,values,selected)=>`<label>${label}<select name="${name}">${options(values,selected)}</select></label>`;
const days=['Sem dia fixo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado','Domingo'];
const goalSelect=value=>select('goal','Objetivo',goals.map(g=>[g,g]),value||goals[0]);
const number=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n);
const weight=v=>number(fromKg(v,state?.profile?.weightUnit||'kg'))+' '+(state?.profile?.weightUnit||'kg');
const date=t=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(t);
let state,view='home',selectedRoutine=null,busy=false,dirty=false,query='',filter='all',registration,installPrompt,pendingRestore,allowReload=false;
let toastTimeout;const drafts=new Map();
const active=()=>state?.sessions.find(x=>x.finishedAt===null);
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function fail(form,error){let box=form?.querySelector('[role=alert]');if(!box&&form){box=document.createElement('div');box.className='error';box.setAttribute('role','alert');form.prepend(box);}if(box){box.textContent=error.message||String(error);box.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
async function commit(fn){const next=change(state,fn);await writeState(next,state.rev);state=next;channel?.postMessage({rev:next.rev});return next;}
const channel='BroadcastChannel' in window?new BroadcastChannel('evolupersonal-pwa-data'+(location.pathname.endsWith('/student.html')?'-student':'')):null;
channel?.addEventListener('message',()=>toast('Os dados mudaram em outra aba. Reabra a página antes de salvar novas alterações.'));
function theme(){document.documentElement.dataset.theme=state?.profile?.theme||'light';$('meta[name=theme-color]').content=state?.profile?.theme==='dark'?'#101d22':'#133d49';}
function closeDialog(force=false){if(busy&&!force)return;if(!force&&dirty&&!confirm('Descartar as alterações ainda não salvas?'))return;dirty=false;dialog.close();dialog.innerHTML='';pendingRestore=null;}
function modal(title,body){dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" type="button" data-cmd="close" aria-label="Fechar">${icon('close')}</button></div>${body}</div>`;dirty=false;if(!dialog.open)dialog.showModal();}
function form(title,kind,fields,entityId='',submit='Salvar'){modal(title,`<form data-kind="${kind}" data-id="${esc(entityId)}">${fields}<div class="dialog-footer">${button('Cancelar','close')}<button class="primary" type="submit">${icon('check')}${submit}</button></div></form>`);}
function navigate(next){if(busy)return;if(dirty&&!confirm('Descartar o rascunho ainda não salvo?'))return;dirty=false;drafts.clear();view=state.profile?.role==='student'&&!['routine','session','settings','history','portal'].includes(next)?'portal':next;query='';filter='all';render();window.scrollTo({top:0});}
const empty=(title,description,action='')=>`<div class="empty"><div class="empty-icon">${icon('train')}</div><h3>${title}</h3><p>${description}</p>${action}</div>`;
const heading=(title,description,action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
function render(){theme();if(!state.profile){renderOnboard();return;}
 const tabs=[['home','Dashboard','home'],['students','Alunos','users'],['routines','Treinos','train'],['library','Biblioteca','library'],['history','Evolução','chart']];
 const nav=(state.profile.role==='student'?[['portal','Minha ficha','home'],['history','Histórico','chart']]:tabs).map(([key,label,image])=>`<button data-cmd="nav" data-view="${key}" ${view===key||(key==='routines'&&['routine','session'].includes(view))?'aria-current="page"':''}>${icon(image)}<span>${label}</span></button>`).join('');
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">E</div><div><strong>EvoluPersonal</strong><small>TREINAMENTO & EVOLUÇÃO</small></div></div><nav class="nav" aria-label="Navegação principal">${nav}</nav><div class="sidebar-bottom"><nav class="nav"><button data-cmd="nav" data-view="settings" ${view==='settings'?'aria-current="page"':''}>${icon('settings')}Configurações</button></nav><div class="sidebar-note">Seu trabalho. Sua evolução.<br>Híbrido ${VERSION}</div></div></aside><div><header class="topbar"><span class="eyebrow">SEU ESPAÇO DE TREINAMENTO</span><div class="mobile-brand"><div class="brand-mark">E</div>EvoluPersonal</div><div class="top-actions"><span class="connection"><span class="dot"></span><span id="connection-label">${navigator.onLine?'Conectado':'Sem conexão'}</span></span>${state.profile.role==='student'?'':'<button class="icon-button" data-cmd="b:modules" aria-label="Módulos">'+icon('library')+'</button>'}<button class="icon-button" data-cmd="nav" data-view="settings" aria-label="Configurações">${icon('settings')}</button><span class="avatar" aria-label="${esc(state.profile.name)}">${esc(initials(state.profile.name))}</span></div></header><main id="main" tabindex="-1">${active()&&view!=='session'?`<div class="active-banner"><div><strong>Seu treino está em andamento</strong><p>${esc(active().title)} · registros salvos neste dispositivo</p></div>${button('Retomar','resume','primary')}</div>`:''}${({home:home,students:students,routines:routines,library:library,history:history,settings:settings,routine:routineDetail,session:sessionView}[view]||betaViews[view]||home)()}<p class="footer-note">EvoluPersonal · ${VERSION} · Dados salvos neste navegador</p></main></div></div>`;
 updateTimer();
}
function renderOnboard(){if(location.pathname.endsWith('/student.html')){root.innerHTML='<main class="loading"><div class="brand-mark">E</div><h1>Espaço do aluno</h1><p>Importe o pacote criptografado enviado pelo seu profissional.</p>'+button('Importar pacote do aluno','restore','primary')+'<p><a href="./index.html">Espaço profissional</a></p></main>';return;}root.innerHTML=`<div class="onboard"><section class="welcome"><div class="brand"><div class="brand-mark">E</div><div><strong>EvoluPersonal</strong><small>TREINAMENTO & EVOLUÇÃO</small></div></div><span class="eyebrow" style="color:#b7d4b8">UM NOVO COMEÇO</span><h1>Planeje com cuidado.<br>Evolua com propósito.</h1><p>Alunos, fichas e cada série do treino em um espaço feito para acompanhar sua rotina.</p><small>SMARTPHONE · TABLET · COMPUTADOR</small></section><main id="main" class="onboard-form"><span class="eyebrow">BEM-VINDO AO SEU ESPAÇO</span><h2 style="margin-top:10px">Vamos começar?</h2><p>Primeiro, conte como podemos chamar você.<br>Seu perfil será salvo neste navegador.</p><form data-kind="onboard">${input('name','Nome do profissional','','text','required minlength="2" maxlength="60" autocomplete="name"')}${select('theme','Aparência',[['light','Clara'],['dark','Escura']],'light')}<button class="primary" type="submit">Salvar e começar ${icon('arrow')}</button></form><p style="font-size:11px">O salvamento é local. Faça backups nas configurações para transferir seus dados entre dispositivos.</p><p><a href="./student.html">Sou aluno: importar meu pacote</a></p></main></div>`;}
function home(){const completed=state.sessions.filter(x=>x.finishedAt),weekStart=new Date();weekStart.setHours(0,0,0,0);weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const weekDays=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);const done=completed.some(s=>new Date(s.finishedAt).toDateString()===d.toDateString());return `<div class="day ${d.toDateString()===new Date().toDateString()?'today':''} ${done?'done':''}"><small>${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'][i]}</small><b>${d.getDate()}</b><span class="dot"></span></div>`;}).join('');const weekCount=completed.filter(x=>x.finishedAt>=weekStart.getTime()).length;
 return heading(`Olá, ${esc(state.profile.name.split(' ')[0])}.`,'Cada bom treino começa com um bom plano.',`<span class="date-pill">${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</span>`)+`<section class="hero"><div><span class="eyebrow">SEU PRÓXIMO PASSO</span><h2>Uma rotina organizada.<br>Mais espaço para evoluir.</h2><p>Monte suas fichas, acompanhe seus alunos e registre o que acontece em cada treino.</p>${button(`${icon('plus')} ${state.students.length?'Montar um treino':'Cadastrar primeiro aluno'}`,state.students.length?'new-routine':'new-student','primary')}</div><div class="hero-art" aria-hidden="true"><div class="rings"></div><div class="hero-stat"><b>${completed.length}</b><span>TREINOS CONCLUÍDOS</span></div><span class="hero-tag">Um passo de cada vez ↗</span></div></section><section class="metrics" aria-label="Resumo"><div class="metric"><div class="metric-icon">${icon('users')}</div><div><b>${state.students.filter(x=>x.active).length}</b><span>Alunos ativos</span></div></div><div class="metric"><div class="metric-icon">${icon('train')}</div><div><b>${state.routines.filter(x=>!x.archived).length}</b><span>Fichas de treino</span></div></div><div class="metric"><div class="metric-icon">${icon('check')}</div><div><b>${weekCount}</b><span>Sessões nesta semana</span></div></div></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Sua semana em movimento</h2><small>Os dias marcados têm sessões concluídas</small></div>${icon('clock')}</div><div class="week">${weekDays}</div><p class="week-foot">${weekCount?`${weekCount} sessão(ões) registrada(s) nesta semana.`:'Seus registros de treino aparecerão aqui.'}</p></section><section class="panel"><div class="section-head"><div><h2>Seus alunos</h2><small>Acompanhamento começa por aqui</small></div>${button('Ver todos ↗','nav','text-button','data-view="students"')}</div>${state.students.length?state.students.slice(-3).reverse().map(x=>`<div class="routine-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.goal)}</small></div>${button('Ver perfil','student-detail','text-button',`data-id="${esc(x.id)}"`)}</div>`).join(''):empty('Seu primeiro aluno está por vir','Cadastre seus alunos para organizar fichas e acompanhar os treinos.',button('Cadastrar aluno','new-student','secondary'))}</section><section class="panel" style="grid-column:1/-1"><div class="section-head"><div><h2>Fichas prontas para treinar</h2><small>Seu planejamento, sempre à mão</small></div>${button('Novo treino +','new-routine','text-button')}</div>${state.routines.filter(x=>!x.archived).length?state.routines.filter(x=>!x.archived).slice(-4).reverse().map(r=>`<div class="routine-row"><div><strong>${esc(r.title)}</strong><small>${r.items.length} exercícios · ${esc(days[r.day])}</small></div>${button('Abrir ficha ↗','open-routine','text-button',`data-id="${esc(r.id)}"`)}</div>`).join(''):empty('Dê forma ao próximo treino','Comece com uma ficha e inclua exercícios da sua biblioteca.',button('Criar primeira ficha','new-routine','secondary'))}</section></div>`;}
function students(){return heading('Alunos','Pessoas, objetivos e acompanhamento.',button(`${icon('plus')} Novo aluno`,'new-student','primary'))+`<div class="toolbar"><input class="search" data-search="students" aria-label="Pesquisar aluno" placeholder="Pesquisar por nome…" value="${esc(query)}"><div class="chips">${[['all','Todos'],['active','Ativos'],['inactive','Inativos']].map(([key,label])=>`<button class="chip ${filter===key?'active':''}" data-cmd="filter" data-filter="${key}">${label}</button>`).join('')}</div></div><div class="cards" id="results">${studentCards()}</div>`;}
function studentCards(){const list=state.students.filter(x=>normalize(x.name).includes(normalize(query))&&(filter==='all'||x.active===(filter==='active')));return list.length?list.map(x=>`<article class="card"><div class="card-top"><div class="student-avatar">${esc(initials(x.name))}</div><span class="badge ${x.active?'green':''}">${x.active?'Ativo':'Inativo'}</span></div><h2>${esc(x.name)}</h2><p>${esc(x.goal)}</p><small>${state.routines.filter(r=>r.studentId===x.id&&!r.archived).length} ficha(s) · ${state.sessions.filter(s=>s.studentId===x.id&&s.finishedAt).length} sessão(ões)</small><div class="actions">${button('Ver perfil','student-detail','secondary',`data-id="${esc(x.id)}"`)}${button('Editar','edit-student','text-button',`data-id="${esc(x.id)}"`)}</div></article>`).join(''):empty('Nenhum aluno encontrado','Cadastre um aluno ou ajuste a pesquisa e o filtro.');}
function studentForm(entity){form(entity?'Editar aluno':'Novo aluno','student',`<div class="form-grid">${input('name','Nome',entity?.name,'text','required minlength="2" maxlength="80"')}${goalSelect(entity?.goal)}<div class="span-2">${input('availability','Disponibilidade (dias e horários)',entity?.availability,'text','maxlength="200"')}</div><div class="span-2">${input('equipment','Equipamentos disponíveis',entity?.equipment,'text','maxlength="200"')}</div><div class="span-2">${textarea('notes','Observações',entity?.notes)}</div></div>`,entity?.id);}
function studentDetail(x){const sessions=state.sessions.filter(s=>s.studentId===x.id&&s.finishedAt);modal('Perfil do aluno',`<div class="history-detail"><div><h1>${esc(x.name)}</h1><span class="badge ${x.active?'green':''}">${x.active?'Aluno ativo':'Aluno inativo'}</span></div><p>${esc(x.goal)}</p><dl><dt>Disponibilidade</dt><dd>${esc(x.availability||'Não informada')}</dd><dt>Equipamentos</dt><dd>${esc(x.equipment||'Não informados')}</dd></dl>${x.notes?`<p>${esc(x.notes)}</p>`:''}<div class="actions">${button('Editar cadastro','edit-student','primary',`data-id="${esc(x.id)}"`)}${button(x.active?'Inativar aluno':'Reativar aluno','toggle-student','secondary',`data-id="${esc(x.id)}"`)}</div><h3>Fichas vinculadas</h3>${state.routines.filter(r=>r.studentId===x.id).map(r=>`<div class="routine-row"><span>${esc(r.title)} ${r.archived?'(arquivada)':''}</span>${button('Abrir','open-routine','text-button',`data-id="${esc(r.id)}"`)}</div>`).join('')||'<p class="muted">Nenhuma ficha vinculada. Escolha este aluno ao criar ou editar uma ficha.</p>'}<h3>Histórico individual</h3>${sessions.length?sessions.slice().reverse().map(s=>`<div class="routine-row"><div>${esc(s.title)}<small>${date(s.finishedAt)} · ${s.sets.length} séries</small></div>${button('Ver','session-detail','text-button',`data-id="${esc(s.id)}"`)}</div>`).join(''):'<p class="muted">Ainda sem sessões concluídas.</p>'}</div>`);}
function library(){return button('Baixar GIFs para uso offline','cache-media','secondary')+'<p id="media-download-progress" role="status"></p>'+heading('Biblioteca','Seus exercícios, organizados do seu jeito.',button(`${icon('plus')} Novo exercício`,'new-exercise','primary'))+`<div class="toolbar"><input class="search" data-search="library" aria-label="Pesquisar exercício" placeholder="Nome, músculo ou equipamento…" value="${esc(query)}"><div class="chips">${[['all','Todos'],['favorites','Favoritos']].map(([key,label])=>`<button class="chip ${filter===key?'active':''}" data-cmd="filter" data-filter="${key}">${label}</button>`).join('')}</div></div><div class="cards" id="results">${exerciseCards()}</div><p class="note">445 exercícios com vínculos de GIF são importados automaticamente, sem duplicar IDs. Abra a animação para conferir a execução e o status de revisão. No APK as mídias estão embarcadas para uso offline.</p>`;}
function exerciseCards(){const list=state.exercises.filter(x=>normalize(`${x.name} ${x.muscle} ${x.equipment}`).includes(normalize(query))&&(filter!=='favorites'||x.favorite));return list.length?list.map(x=>`<article class="card"><div class="card-top"><div class="metric-icon">${icon('train')}</div><button class="icon-button" data-cmd="favorite" data-id="${esc(x.id)}" aria-label="${x.favorite?'Remover dos favoritos':'Favoritar'} ${esc(x.name)}" aria-pressed="${x.favorite}">${icon('star')}</button></div><h2>${esc(x.name)}</h2><p>${esc(x.muscle)} · ${esc(x.equipment||'Sem equipamento informado')}</p>${x.instructions?`<p>${esc(x.instructions)}</p>`:''}${x.media?.sha?button('Ver animação','view-media','primary',`data-id="${esc(x.id)}"`):''}${button('Editar exercício','edit-exercise','secondary',`data-id="${esc(x.id)}"`)}</article>`).join(''):empty('Uma biblioteca com a sua identidade','Cadastre os exercícios que você utiliza para começar a montar suas fichas.');}
function exerciseForm(x){form(x?'Editar exercício':'Novo exercício','exercise',`${input('name','Nome do exercício',x?.name,'text','required minlength="2" maxlength="120"')}<div class="form-grid">${input('muscle','Grupo muscular',x?.muscle,'text','required minlength="2" maxlength="50"')}${input('equipment','Equipamento',x?.equipment,'text','maxlength="100"')}</div>${input('secondary','Músculos secundários (separados por vírgula)',x?.secondary?.join(', ')||'','text','maxlength="500"')}${textarea('instructions','Instruções de execução',x?.instructions,2000)}`,x?.id);}
function routines(){return heading('Treinos','Fichas simples para uma execução bem planejada.',button(`${icon('plus')} Novo treino`,'new-routine','primary'))+`<div class="toolbar"><input class="search" data-search="routines" aria-label="Pesquisar ficha" placeholder="Pesquisar ficha…" value="${esc(query)}"><div class="chips">${[['all','Ativas'],['archived','Arquivadas']].map(([key,label])=>`<button class="chip ${filter===key?'active':''}" data-cmd="filter" data-filter="${key}">${label}</button>`).join('')}</div></div><div class="cards" id="results">${routineCards()}</div>`;}
function routineCards(){const list=state.routines.filter(r=>r.archived===(filter==='archived')&&normalize(r.title).includes(normalize(query)));return list.length?list.slice().reverse().map(r=>`<article class="card"><div class="card-top"><span class="badge">${esc(days[r.day])}</span>${icon('train')}</div><h2>${esc(r.title)}</h2><p>${esc(state.students.find(x=>x.id===r.studentId)?.name||'Treino pessoal')} · ${r.items.length} exercício(s)</p>${button('Abrir ficha ↗','open-routine','primary',`data-id="${esc(r.id)}"`)}</article>`).join(''):empty('Seu próximo treino começa aqui','Crie uma ficha, escolha o aluno e inclua exercícios da biblioteca.',button('Criar ficha','new-routine','secondary'));}
function routineForm(r){form(r?'Editar ficha':'Nova ficha','routine',`${input('title','Nome da ficha',r?.title,'text','required minlength="2" maxlength="60"')}<div class="form-grid">${select('studentId','Vincular ao aluno',[['','Treino pessoal'],...state.students.filter(x=>x.active||x.id===r?.studentId).map(x=>[x.id,`${x.name}${x.active?'':' (inativo)'}`])],r?.studentId||'')}${select('day','Dia programado',days.map((d,i)=>[i,d]),r?.day||0)}</div>${textarea('notes','Observações da ficha',r?.notes)}`,r?.id);}
function routineDetail(){const r=state.routines.find(x=>x.id===selectedRoutine);if(!r)return empty('Ficha não encontrada','Volte à lista de treinos.',button('Voltar','nav','secondary','data-view="routines"'));
 return button('← Todos os treinos','nav','text-button','data-view="routines"')+heading(esc(r.title),`${esc(state.students.find(x=>x.id===r.studentId)?.name||'Treino pessoal')} · ${esc(days[r.day])}`,button('Editar ficha','edit-routine','secondary',`data-id="${esc(r.id)}"`))+`<div class="actions" style="margin-bottom:20px">${button('Duplicar ficha','duplicate','secondary',`data-id="${esc(r.id)}"`)}${button(r.archived?'Restaurar ficha':'Arquivar ficha','archive','secondary',`data-id="${esc(r.id)}"`)}${!r.archived?button(`${icon('plus')} Adicionar exercício`,'add-item','primary',`data-id="${esc(r.id)}"`):''}</div>${r.notes?`<p class="note">${esc(r.notes)}</p>`:''}<div class="session-list">${r.items.length?r.items.map((item,i)=>`<article class="card"><div class="section-head"><div><span class="eyebrow">EXERCÍCIO ${i+1}</span><h2>${esc(state.exercises.find(x=>x.id===item.exerciseId)?.name)}</h2><small>${item.sets} séries × ${item.reps}–${item.repsMax??item.reps} repetições · ${item.rest}s de descanso<br>${esc(methods[item.method||'NORMAL'])}${item.block?' · Bloco '+esc(item.block):''} · Carga ${item.load==null?'livre':weight(item.load)}<br>RIR ${item.rir??'—'} · RPE ${item.rpe??'—'} · Cadência ${esc(item.cadence||'livre')}${item.notes?'<br>'+esc(item.notes):''}</small></div>${icon('train')}</div>${!r.archived?`<div class="actions">${button('Editar prescrição','edit-item','secondary',`data-id="${esc(r.id)}" data-index="${i}"`)}${button('↑','move-up','secondary',`data-id="${esc(r.id)}" data-index="${i}" aria-label="Mover exercício ${i+1} para cima" ${i===0?'disabled':''}`)}${button('↓','move-down','secondary',`data-id="${esc(r.id)}" data-index="${i}" aria-label="Mover exercício ${i+1} para baixo" ${i===r.items.length-1?'disabled':''}`)}${button('Remover','remove-item','text-button',`data-id="${esc(r.id)}" data-index="${i}"`)}</div>`:''}</article>`).join(''):empty('Escolha os exercícios da ficha','Cadastre exercícios na biblioteca e inclua-os neste treino.')}</div>${!r.archived?`<div class="actions" style="margin-top:24px">${button(`${icon('train')} Iniciar treino`,'start-session','primary',`data-id="${esc(r.id)}" ${r.items.length?'':'disabled'}`)}</div>`:''}`;}
function itemForm(r,index){const existing=index!==null?prescription(r.items[index]):prescription({sets:3,reps:10,rest:state.profile.defaultRest??90});const available=state.exercises.filter(x=>x.id===existing?.exerciseId||!r.items.some(i=>i.exerciseId===x.id));if(!available.length){toast('Cadastre outro exercício na biblioteca antes de incluir.');return;}
 form(index!==null?'Editar prescrição':'Adicionar exercício','item',`${input('exerciseSearch','Pesquisar exercício','','search','autocomplete="off" placeholder="Nome, músculo ou equipamento" data-exercise-search')}${select('exerciseId','Exercício',available.map(x=>[x.id,`${x.name} · ${x.muscle}`]),existing?.exerciseId)}<small id="exercise-match-count" role="status">${available.length} exercícios disponíveis</small><div class="form-grid">${input('sets','Séries',existing?.sets||3,'number','required min="1" max="15" step="1"')}${input('reps','Repetições',existing?.reps||10,'number','required min="1" max="1000" step="1"')}<div class="span-2">${input('rest','Descanso (segundos)',existing?.rest??90,'number','required min="0" max="3600" step="1"')}</div></div>${input('repsMax','Repetições máximas',existing.repsMax??10,'number','required min="1" max="1000"')}${input('load',`Carga-alvo (${state.profile.weightUnit||'kg'}, opcional)`,existing.load===null?'':fromKg(existing.load,state.profile.weightUnit||'kg'),'number','min="0" max="1000" step="any"')}<div class="form-grid">${input('rir','RIR-alvo',existing.rir??'','number','min="0" max="10"')}${input('rpe','RPE-alvo',existing.rpe??'','number','min="1" max="10"')}</div>${input('cadence','Cadência',existing.cadence||'','text','maxlength="30"')}${input('seconds','Duração-alvo (segundos)',existing.seconds||0,'number','required min="0" max="7200"')}${select('method','Método',Object.entries(methods),existing.method)}${input('block','Bloco para associar exercícios',existing.block||'','text','maxlength="30"')}<div class="form-grid">${input('rounds','Rodadas',existing.rounds||1,'number','required min="1" max="100"')}${input('work','Execução por rodada (s)',existing.work||30,'number','required min="1" max="3600"')}${input('interval','Intervalo (s)',existing.interval??15,'number','required min="0" max="3600"')}</div>${textarea('notes','Notas técnicas',existing.notes||'')}<input type="hidden" name="index" value="${index===null?'':index}">`,r.id,'Salvar na ficha');}
function sessionView(){const s=active();if(!s)return empty('Nenhum treino em andamento','Escolha uma ficha para iniciar.',button('Ver treinos','nav','primary','data-view="routines"'));
 return heading(esc(s.title),`${esc(s.studentName||'Treino pessoal')} · Iniciado em ${date(s.startedAt)}`,button('Concluir treino','finish-session','primary',`data-id="${esc(s.id)}" ${s.sets.length?'':'disabled'}`))+`<section class="panel" style="margin-bottom:20px"><div class="section-head" style="margin-bottom:0"><div><h2>Descanso entre séries</h2><small>O relógio é retomado ao reabrir esta sessão.</small></div><strong class="timer" data-until="${s.restUntil}">00:00</strong></div></section><div class="actions" style="margin-bottom:20px">${button(s.pausedAt?'Retomar treino':'Pausar treino','pause-session','secondary')}${button('Check-in de fadiga','fatigue','secondary')}</div><p class="note">${s.pausedAt?'Treino pausado — registro de séries bloqueado.':'Treino em andamento.'}</p><p role="timer" class="timer" id="method-clock"></p>${s.timer?button('Parar temporizador','stop-method','secondary'):''}<p class="note">${sessionProgress(s).completed}/${sessionProgress(s).planned} séries de trabalho planejadas registradas. Aquecimentos ficam separados.</p><div class="session-list">${s.items.filter(item=>!item.replaced).map((item,i)=>{const records=s.sets.filter(t=>t.exerciseId===item.exerciseId),d=drafts.get(item.exerciseId)||{};return `<article class="card"><span class="eyebrow">${i+1} · ${esc(item.muscle)}</span><h2>${esc(item.name)}</h2><p>${item.sets} séries × ${item.reps}–${item.repsMax??item.reps} repetições · ${item.rest}s de descanso<br>${methods[item.method||'NORMAL']} · ${esc(item.block||'')} · carga-alvo ${item.load===null||item.load===undefined?'Livre':weight(item.load)} · cadência ${esc(item.cadence||'Livre')}<br>${esc(item.notes||'')}</p><p class="note">${esc(methodGuides[item.method||'NORMAL'])} ${item.seconds?'Duração-alvo: '+item.seconds+'s.':''}</p><div class="actions">${button('Iniciar método','method-timer','secondary',`data-id="${esc(item.exerciseId)}"`)}${state.exercises.find(e=>e.id===item.exerciseId)?.media?.sha?button('Ver animação','view-media','secondary',`data-id="${esc(item.exerciseId)}"`):''}${button('Substituir exercício','substitute','secondary',`data-id="${esc(item.exerciseId)}"`)}</div><div class="series">${records.map((t,k)=>`<span>#${k+1} · ${t.reps} × ${weight(t.load)} · RIR ${t.rir??'—'} · ${esc(t.type||'NORMAL')} ${button('Corrigir','edit-set','text-button',`data-index="${s.sets.indexOf(t)}" aria-label="Corrigir série ${k+1} de ${esc(item.name)}"`)}</span>`).join('')}</div><form class="set-form" data-kind="set" data-id="${esc(s.id)}" data-exercise="${esc(item.exerciseId)}">${input('reps','Repetições',d.reps??item.reps,'number','required min="1" max="1000" step="1"')}${input('load',`Carga (${state.profile.weightUnit||'kg'})`,d.load??fromKg(item.load??0,state.profile.weightUnit||'kg'),'number','required min="0" max="1000" step="any" inputmode="decimal"')}${input('rir','RIR (opcional)',d.rir??'','number','min="0" max="10" step="1"')}${input('rpe','RPE (opcional)',d.rpe??'','number','min="1" max="10" step="1"')}${select('type','Tipo de série',[['NORMAL','Trabalho'],['AQUECIMENTO','Aquecimento'],['BACKOFF','Back-off'],['DROP','Drop'],['FALHA','Falha']],d.type||'NORMAL')}${input('notes','Observação da série',d.notes||'','text','maxlength="180"')}<button class="primary" type="submit" ${s.pausedAt?'disabled':''}>${icon('plus')} Registrar série ${records.length+1}</button></form></article>`;}).join('')}</div><p class="note">Cada série é salva após a confirmação. Você pode sair e retomar esta sessão. A ficha original e os nomes usados no treino ficam preservados.</p>`;}
function history(){const completed=state.sessions.filter(s=>s.finishedAt).slice().reverse();const volume=completed.reduce((n,s)=>n+sessionVolume(s),0);return heading('Evolução','O que foi feito, registrado para acompanhar.',state.profile.role==='student'?'':button('Análise detalhada','b:view','primary','data-view="analysis"'))+`<div class="metrics"><div class="metric"><div><b>${completed.length}</b><span>Sessões concluídas</span></div></div><div class="metric"><div><b>${completed.reduce((n,s)=>n+s.sets.length,0)}</b><span>Séries registradas</span></div></div><div class="metric"><div><b>${number(volume)}</b><span>Volume total (kg × rep.)</span></div></div></div><div class="cards">${completed.length?completed.map(s=>`<article class="card"><span class="badge green">Concluído</span><h2 style="margin-top:16px">${esc(s.title)}</h2><p>${esc(s.studentName||'Treino pessoal')}<br>${date(s.finishedAt)}</p><small>${s.sets.length} séries · ${number(sessionVolume(s))} kg × rep.</small><div class="actions">${button('Ver sessão','session-detail','secondary',`data-id="${esc(s.id)}"`)}</div></article>`).join(''):empty('Sua evolução será construída aqui','Conclua uma sessão para consultar os registros e o volume movimentado.')}</div>`;}
function sessionDetail(s){modal('Registro da sessão',`<div class="history-detail"><h2>${esc(s.title)}</h2><p>${esc(s.studentName||'Treino pessoal')} · ${date(s.finishedAt||s.startedAt)}</p>${s.items.map(item=>`<article class="card"><h3>${esc(item.name)}${item.replaced?' (substituído)':''}</h3><small>Planejado: ${item.sets} × ${item.reps} · descanso ${item.rest}s</small>${s.sets.filter(t=>t.exerciseId===item.exerciseId).map((t,i)=>`<p>Série ${i+1} · ${t.reps} × ${weight(t.load)} · RIR ${t.rir??'—'}</p>`).join('')||'<p class="muted">Sem séries registradas.</p>'}</article>`).join('')}<h3>Ocorrências da sessão</h3>${(s.events||[]).map(e=>`<p>${esc(e)}</p>`).join('')||'<p>Sem ocorrências.</p>'}<p class="note">O registro mantém a ficha e os nomes utilizados nesta sessão, mesmo após editar os cadastros.</p></div>`);}
function settings(){return heading('Configurações','Seu perfil, seus dados e suas preferências.')+`<div class="settings-grid"><section class="panel"><h2>Perfil profissional</h2><form data-kind="profile">${input('name','Nome do profissional',state.profile.name,'text','required minlength="2" maxlength="60"')}${select('theme','Aparência',[['light','Clara'],['dark','Escura']],state.profile.theme)}${select('experience','Experiência',['Iniciante','Intermediário','Avançado'].map(x=>[x,x]),state.profile.experience||'Iniciante')}${input('equipment','Equipamentos padrão',state.profile.equipment||'','text','maxlength="200"')}${goalSelect(state.profile.goal)}<div class="form-grid">${select('weightUnit','Unidade de carga',[['kg','kg'],['lb','lb']],state.profile.weightUnit||'kg')}${select('lengthUnit','Unidade de comprimento',[['cm','cm'],['in','polegadas']],state.profile.lengthUnit||'cm')}</div>${input('defaultRest','Descanso padrão (segundos)',state.profile.defaultRest??90,'number','required min="0" max="3600"')}<button class="primary" type="submit">Salvar perfil</button></form></section><section class="panel"><h2>Backup e recuperação</h2><p>Exporte um arquivo criptografado com senha para guardar uma cópia ou transferir seus dados para outro dispositivo.</p><div class="actions">${button(`${icon('download')} Exportar backup`,'export','primary')}${button('Restaurar backup','restore','secondary')}</div><p>Guarde a senha: ela não é armazenada. Esta base inicial aceita backups do EvoluPersonal PWA. Backups Android e EvoluFísico2 ainda não são importados.</p></section><section class="panel"><h2>Aplicativo e atualização</h2><p>Versão ${VERSION} · Beta híbrido</p><div class="actions">${window.NativeBridge?.isNative?'':button('Instalar aplicativo','install','secondary')}${button('Verificar atualização','check-update','secondary')}${registration?.waiting?button('Atualizar agora','apply-update','primary'):''}</div><p id="pwa-status">${registration?.active?'Versão offline instalada neste navegador.':'Preparando o acesso offline. A instalação depende do navegador e das permissões.'}</p></section><section class="panel"><h2>Armazenamento local</h2><p>Os dados ficam neste navegador e neste endereço. Limpar os dados do site remove os registros locais. O backup permite recuperá-los.</p>${button('Solicitar armazenamento persistente','persist','secondary')}<p id="storage-status">O navegador decide se pode manter o armazenamento persistente.</p></section></div>`;}
function backupForm(restore){form(restore?'Restaurar backup':'Exportar backup',restore?'restore':'export',`${restore?'<label>Arquivo de backup<input name="file" type="file" accept=".evp,json,application/json" required></label>':''}${input('password','Senha do backup','','password','required minlength="8" autocomplete="new-password"')}${!restore?input('repeat','Repita a senha','','password','required minlength="8" autocomplete="new-password"'):''}<p class="muted" style="font-size:12px">${restore?'O arquivo será validado antes de pedir confirmação para substituir os dados atuais.':'A senha protege os dados deste arquivo. Guarde-a para conseguir restaurar.'}</p>`,'',restore?'Validar arquivo':'Exportar arquivo');}
function assertEditable(r){if(!r||r.archived)throw new Error('Restaure a ficha antes de editar.');if(active()?.routineId===r.id)throw new Error('Conclua a sessão antes de alterar esta ficha.');}
function updateTimer(){const current=active(),clock=$('#method-clock');if(current&&clock){const phase=timerPhase(current.timer,current.pausedAt||Date.now());clock.textContent=phase?`${phase.label} · rodada ${phase.round}/${current.timer.rounds} · ${phase.remaining}s`:'';}const timer=$('[data-until]');if(timer){const seconds=Math.max(0,Math.ceil((Number(timer.dataset.until)-(current?.pausedAt||Date.now()))/1000));timer.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}}
setInterval(updateTimer,1000);
document.addEventListener('input',event=>{const form=event.target.closest('form');if(form){dirty=true;if(form.dataset.kind==='set')drafts.set(form.dataset.exercise,Object.fromEntries(new FormData(form)));}if(event.target.hasAttribute('data-exercise-search')){const picker=form.querySelector('[name=exerciseId]');const r=state.routines.find(x=>x.id===form.dataset.id);const index=form.querySelector('[name=index]').value;const current=index===''?null:r.items[Number(index)].exerciseId;const available=state.exercises.filter(x=>x.id===current||!r.items.some(i=>i.exerciseId===x.id));const matches=new Set(filterExercises(available,event.target.value).map(x=>x.id));for(const option of picker.options){option.hidden=!matches.has(option.value);option.disabled=option.hidden;}if(!matches.has(picker.value))picker.value=picker.querySelector('option:not([disabled])')?.value||'';picker.required=true;form.querySelector('#exercise-match-count').textContent=matches.size+' exercícios encontrados';}if(event.target.dataset.search){query=event.target.value;$('#results').innerHTML=({students:studentCards,library:exerciseCards,routines:routineCards}[event.target.dataset.search])();}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
window.addEventListener('beforeunload',e=>{if(dirty&&!allowReload){e.preventDefault();e.returnValue='';}});
for(const name of ['online','offline'])window.addEventListener(name,()=>{const label=$('#connection-label');if(label)label.textContent=navigator.onLine?'Conectado':'Sem conexão';});
document.addEventListener('submit',async event=>{
 const f=event.target;if(!f.matches('form[data-kind]'))return;event.preventDefault();if(busy)return;busy=true;
 const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;const d=Object.fromEntries(new FormData(f)),kind=f.dataset.kind;
 try {
  if(kind.startsWith('b:')){await betaSubmit(f,d);return;}
  if(kind==='onboard'||kind==='profile'){await commit(s=>{s.profile={...s.profile,name:d.name.trim(),theme:d.theme,...(kind==='profile'?{experience:d.experience,equipment:d.equipment.trim(),goal:d.goal,weightUnit:d.weightUnit,lengthUnit:d.lengthUnit,defaultRest:Number(d.defaultRest)}:{experience:'Iniciante',equipment:'',goal:'Condicionamento',weightUnit:'kg',lengthUnit:'cm',defaultRest:90})};});dirty=false;view='home';render();toast('Perfil salvo neste dispositivo.');navigator.storage?.persist?.().catch(()=>{});}
  if(kind==='fatigue'){await commit(s=>{s.sessions.find(x=>!x.finishedAt).fatigue=Number(d.fatigue);});dirty=false;closeDialog(true);render();}
  if(kind==='substitute'){await commit(s=>substitute(s,d.original,d.replacement));dirty=false;closeDialog(true);render();}
  if(kind==='student'){await commit(s=>saveStudent(s,{id:f.dataset.id,name:d.name.trim(),goal:d.goal,equipment:d.equipment.trim(),availability:d.availability.trim(),notes:d.notes.trim()}));dirty=false;closeDialog(true);render();toast('Aluno salvo.');}
  if(kind==='exercise'){await commit(s=>saveExercise(s,{id:f.dataset.id,name:d.name.trim(),muscle:d.muscle.trim(),equipment:d.equipment.trim(),instructions:d.instructions.trim(),secondary:(d.secondary||'').split(',').map(x=>x.trim()).filter(Boolean)}));dirty=false;closeDialog(true);render();toast('Exercício salvo.');}
  if(kind==='routine'){let saved;await commit(s=>{const old=s.routines.find(x=>x.id===f.dataset.id);const draft={id:old?.id||id(),title:d.title.trim(),studentId:d.studentId||null,day:Number(d.day),notes:d.notes.trim()};saveRoutine(s,draft);saved=draft.id;});selectedRoutine=saved;view='routine';dirty=false;closeDialog(true);render();toast('Ficha salva.');}
  if(kind==='item'){await commit(s=>{const r=s.routines.find(x=>x.id===f.dataset.id);assertEditable(r);const item={exerciseId:d.exerciseId,sets:Number(d.sets),reps:Number(d.reps),rest:Number(d.rest),repsMax:Number(d.repsMax),load:d.load===''?null:toKg(Number(d.load),state.profile.weightUnit||'kg'),rir:d.rir===''?null:Number(d.rir),rpe:d.rpe===''?null:Number(d.rpe),cadence:d.cadence.trim(),seconds:Number(d.seconds),method:d.method,block:d.block.trim(),rounds:Number(d.rounds),work:Number(d.work),interval:Number(d.interval),notes:d.notes.trim()};validatePrescription(item);if(d.index==='')r.items.push(item);else r.items[Number(d.index)]=item;});dirty=false;closeDialog(true);render();toast('Prescrição salva.');}
  if(kind==='correct-set'){await commit(s=>correctSet(s,Number(d.index),{reps:Number(d.reps),load:toKg(Number(d.load),state.profile.weightUnit||'kg'),rir:d.rir===''?null:Number(d.rir),rpe:d.rpe===''?null:Number(d.rpe),type:d.type,notes:d.notes.trim()}));dirty=false;closeDialog(true);render();toast('Série corrigida. O valor anterior ficou no registro.');}
  if(kind==='set'){await commit(s=>recordSet(s,f.dataset.id,f.dataset.exercise,{reps:Number(d.reps),load:toKg(Number(d.load),state.profile.weightUnit||'kg'),rir:d.rir===''?null:Number(d.rir),rpe:d.rpe===''?null:Number(d.rpe),notes:d.notes?.trim()||'',type:d.type||'NORMAL'}));drafts.delete(f.dataset.exercise);dirty=drafts.size>0;render();toast('Série registrada e salva.');}
  if(kind==='export'){
   if(d.password!==d.repeat)throw new Error('As senhas precisam ser iguais.');const file=await exportBackup(state,d.password);await download(`EvoluPersonal-${new Date().toISOString().slice(0,10)}.evp`,file);dirty=false;closeDialog(true);toast('Arquivo preparado. Confirme o download no navegador.');
  }
  if(kind==='restore'){
   const file=f.querySelector('[name=file]').files[0];if(!file||file.size>10*1024*1024)throw new Error('Selecione um backup de até 10 MB.');const restored=await importBackup(await file.text(),d.password);pendingRestore=restored;dirty=false;modal('Confirmar restauração',`<p>O backup contém <strong>${restored.students.length} alunos, ${restored.routines.length} fichas e ${restored.sessions.length} sessões</strong>.</p><p class="note">A restauração substituirá todos os dados deste navegador. Exporte uma cópia dos dados atuais antes de continuar, se precisar preservá-los.</p><div class="dialog-footer">${button('Cancelar','close')}${button('Substituir dados e restaurar','confirm-restore','danger')}</div>`);pendingRestore=restored;
  }
 }catch(error){fail(f,error);}finally{busy=false;if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('click',async event=>{
 const target=event.target.closest('[data-cmd]');if(!target||busy)return;const cmd=target.dataset.cmd,entityId=target.dataset.id,index=Number(target.dataset.index);
 try {
  if(cmd.startsWith('b:')){if(state.profile?.role==='student'&&!['b:message'].includes(cmd))throw new Error('Use o espaço profissional para acessar este módulo.');busy=true;try{await betaClick(target.dataset);}finally{busy=false;}return;}
  if(state.profile?.role==='student'&& !['nav','close','open-routine','resume','session-detail','export','restore','install','check-update','apply-update','persist','start-session','finish-session','pause-session','method-timer','stop-method','edit-set','view-media','confirm-restore','fatigue'].includes(cmd))throw new Error('Esta edição pertence ao espaço profissional.');
  if(cmd==='nav'){if(dialog.open)closeDialog();if(!dialog.open)navigate(target.dataset.view);return;}
  if(cmd==='close'){closeDialog();return;}
  if(cmd==='pause-session'){await commit(s=>pauseSession(s,!active().pausedAt));render();return;}
  if(cmd==='fatigue'){form('Fadiga percebida','fatigue',select('fatigue','Fadiga (5 = maior fadiga)',[1,2,3,4,5].map(x=>[x,x+'/5']),active()?.fatigue||3));return;}
  if(cmd==='method-timer'){await commit(s=>startMethod(s,entityId));render();return;}
  if(cmd==='stop-method'){await commit(s=>{s.sessions.find(x=>!x.finishedAt).timer=null;});render();return;}
  if(cmd==='edit-set'){const t=active()?.sets[index];if(!t)throw new Error('Série indisponível.');form('Corrigir série registrada','correct-set',input('reps','Repetições',t.reps,'number','required min="1" max="1000"')+input('load','Carga ('+(state.profile.weightUnit||'kg')+')',fromKg(t.load,state.profile.weightUnit||'kg'),'number','required min="0" max="2204" step="any"')+input('rir','RIR',t.rir??'','number','min="0" max="10"')+input('rpe','RPE',t.rpe??'','number','min="1" max="10"')+select('type','Tipo de série',[['NORMAL','Trabalho'],['AQUECIMENTO','Aquecimento'],['BACKOFF','Back-off'],['DROP','Drop'],['FALHA','Falha']],t.type||'NORMAL')+input('notes','Observação',t.notes||'','text','maxlength="180"')+'<input type="hidden" name="index" value="'+index+'">');return;}
  if(cmd==='substitute'){form('Substituir exercício','substitute','<input name="original" type="hidden" value="'+esc(entityId)+'">'+select('replacement','Novo exercício',state.exercises.filter(e=>!active().items.some(i=>i.exerciseId===e.id)).map(e=>[e.id,e.name]),''));return;}
  if(cmd==='new-student'){studentForm();return;}if(cmd==='edit-student'){studentForm(state.students.find(x=>x.id===entityId));return;}if(cmd==='student-detail'){studentDetail(state.students.find(x=>x.id===entityId));return;}
  if(cmd==='cache-media'){if(window.NativeBridge?.isNative){toast('Os GIFs já estão incluídos neste APK.');return;}if(!('caches' in window))throw new Error('O navegador não permite armazenamento offline de mídias.');if(!confirm('Baixar 442 GIFs (cerca de 135 MB) para uso offline neste navegador?'))return;busy=true;try{const manifest=await (await fetch('./media-manifest.json')).json();const paths=[...new Set(manifest.items.map(x=>x.path))];const cache=await caches.open('evolupersonal-media-v1');for(let i=0;i<paths.length;i++){const url=new URL('./'+paths[i],location.href);if(!await cache.match(url)){const response=await fetch(url);if(!response.ok)throw new Error('Falha na mídia '+(i+1)+'. Os arquivos concluídos foram preservados; tente novamente.');await cache.put(url,response);}const status=$('#media-download-progress');if(status)status.textContent=`${i+1}/${paths.length} GIFs disponíveis offline.`;}toast('Todos os GIFs estão disponíveis offline.');}finally{busy=false;}return;}
  if(cmd==='view-media'){const e=state.exercises.find(x=>x.id===entityId);if(!e?.media?.sha||!/^[a-f0-9]{40}$/.test(e.media.sha))throw new Error('GIF não disponível para este exercício.');modal('Animação do exercício',`<h3>${esc(e.name)}</h3><img class="exercise-gif" src="./media/${e.media.sha}.gif" alt="Animação vinculada a ${esc(e.name)}"><p class="note">Status da origem: ${esc(e.media.review||'Revisão não informada')}. ${e.media.pending?'Correspondência ainda pendente de revisão visual.':'Vínculo importado; não implica aprovação biomecânica integral.'}</p><p data-media-error role="status"></p>`);dialog.querySelector('img').addEventListener('error',()=>{dialog.querySelector('[data-media-error]').textContent='Não foi possível carregar o GIF. Na versão web, conecte-se para baixar a mídia.';});return;}
  if(cmd==='new-exercise'){exerciseForm();return;}if(cmd==='edit-exercise'){exerciseForm(state.exercises.find(x=>x.id===entityId));return;}
  if(cmd==='new-routine'){routineForm();return;}if(cmd==='edit-routine'){const r=state.routines.find(x=>x.id===entityId);assertEditable(r);routineForm(r);return;}
  if(cmd==='open-routine'){if(dialog.open)closeDialog();if(dialog.open)return;selectedRoutine=entityId;navigate('routine');return;}
  if(cmd==='add-item'||cmd==='edit-item'){const r=state.routines.find(x=>x.id===entityId);assertEditable(r);itemForm(r,cmd==='add-item'?null:index);return;}
  if(cmd==='filter'){filter=target.dataset.filter;render();return;}
  if(cmd==='resume'){navigate('session');return;}if(cmd==='session-detail'){sessionDetail(state.sessions.find(x=>x.id===entityId));return;}
  if(cmd==='export'||cmd==='restore'){backupForm(cmd==='restore');return;}
  if(cmd==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Use o menu do navegador: Instalar aplicativo ou Adicionar à tela inicial, quando disponível.');return;}
  if(cmd==='check-update'){if(window.NativeBridge?.isNative){toast('Atualize instalando o próximo APK beta por cima desta versão. Use o link de distribuição do projeto.');return;}if(!registration)throw new Error('O acesso offline ainda não foi instalado. Reabra a página com conexão.');await registration.update();if(registration.waiting){render();toast('Atualização pronta. Use Atualizar agora nas configurações.');}else toast('Verificação concluída. Uma nova versão aparecerá aqui quando estiver pronta.');return;}
  if(cmd==='apply-update'){if(dirty||active())throw new Error('Salve os rascunhos e conclua a sessão antes de atualizar.');if(registration?.waiting){allowReload=true;registration.waiting.postMessage({type:'APPLY_UPDATE'});}return;}
  if(cmd==='persist'){const granted=await navigator.storage?.persist?.();$('#storage-status').textContent=granted?'Armazenamento persistente autorizado neste navegador.':'O navegador não autorizou armazenamento persistente. Mantenha backups atualizados.';return;}
  busy=true;
  if(cmd==='favorite'){await commit(s=>{const x=s.exercises.find(x=>x.id===entityId);x.favorite=!x.favorite;});render();}
  if(cmd==='toggle-student'){const x=state.students.find(x=>x.id===entityId);if(!confirm(`${x.active?'Inativar':'Reativar'} ${x.name}? Fichas e histórico serão preservados.`))return;await commit(s=>{s.students.find(x=>x.id===entityId).active=!x.active;});closeDialog(true);render();toast('Cadastro atualizado.');}
  if(cmd==='duplicate'){await commit(s=>{const r=s.routines.find(x=>x.id===entityId);s.routines.push({...structuredClone(r),id:id(),title:(r.title+' (cópia)').slice(0,60),studentId:null,archived:false});});toast('Cópia independente criada em Treinos.');}
  if(cmd==='archive'){const r=state.routines.find(x=>x.id===entityId);if(active()?.routineId===r.id)throw new Error('Conclua a sessão antes de arquivar.');if(!confirm(r.archived?'Restaurar esta ficha?':'Arquivar esta ficha? O histórico será preservado.'))return;await commit(s=>{s.routines.find(x=>x.id===entityId).archived=!r.archived;});render();}
  if(cmd==='move-up'||cmd==='move-down'){await commit(s=>{const r=s.routines.find(x=>x.id===entityId);assertEditable(r);const next=index+(cmd==='move-up'?-1:1);if(next<0||next>=r.items.length)return;[r.items[index],r.items[next]]=[r.items[next],r.items[index]];});render();}
  if(cmd==='remove-item'){if(!confirm('Retirar este exercício da ficha? As sessões anteriores serão preservadas.'))return;await commit(s=>{const r=s.routines.find(x=>x.id===entityId);assertEditable(r);r.items.splice(index,1);});render();}
  if(cmd==='start-session'){await commit(s=>startSession(s,entityId));dirty=false;view='session';render();toast('Sessão iniciada.');}
  if(cmd==='finish-session'){const s=active();const missing=sessionProgress(s).missing;if(!confirm(`Concluir a sessão com ${s.sets.length} séries registradas? ${missing} série(s) planejada(s) ainda não foram registradas. ${dirty?'Há rascunho não salvo que será descartado.':''}`))return;await commit(s=>finishSession(s,entityId));dirty=false;drafts.clear();view='history';render();toast('Treino concluído e salvo no histórico.');}
  if(cmd==='confirm-restore'){if(!pendingRestore)throw new Error('Selecione o arquivo novamente.');const restored=structuredClone(pendingRestore);restored.rev=state.rev+1;validate(restored);if(location.pathname.endsWith('/student.html')!==(restored.profile?.role==='student'))throw new Error('Abra pacotes do aluno no Espaço do aluno; backups profissionais na página principal.');await writeState(restored,state.rev);state=restored;channel?.postMessage({rev:state.rev});dirty=false;drafts.clear();closeDialog(true);view='home';render();toast('Backup restaurado.');}
 }catch(error){fail(dialog.open?dialog:null,error);}finally{busy=false;}
});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
async function setupPwa(){if(window.NativeBridge?.isNative||!('serviceWorker' in navigator))return;try{
 registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
 registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Nova versão disponível. Atualize nas configurações quando terminar seu trabalho.');});});
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(allowReload)location.reload();});
 if(registration.waiting)toast('Uma atualização está pronta nas configurações.');
}catch{toast('Acesso offline indisponível nesta publicação. Seus registros locais continuam salvos.');}}
async function boot(){try{state=await readState();if(state.profile?.role==='student')view='portal';else{const response=await fetch('./catalog.json');if(!response.ok)throw new Error('Catálogo embarcado indisponível.');const catalog=await response.json();const probe=structuredClone(state);if(mergeLinkedCatalog(probe,catalog))await commit(s=>mergeLinkedCatalog(s,catalog));}render();setupPwa();}catch(error){root.innerHTML=`<main class="loading"><div class="brand-mark">E</div><h1>Não foi possível abrir os dados</h1><p class="error">${esc(error.message)}</p><button class="primary" id="retry">Tentar novamente</button><p>Nenhum dado foi apagado.</p></main>`;$('#retry').onclick=boot;}}

async function download(name,text,type='application/json') {
 if(window.NativeBridge?.isNative){await window.NativeBridge.saveFile(name,text);return;}
 const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
initBeta({state:()=>state,commit,render,toast,esc,button,input,select,textarea,form,modal,download,weight,currentView:()=>view,done(next){dirty=false;closeDialog(true);if(next)view=next;render();}});

boot();
